/* OpenVoiceCS-Bench site renderer.
 *
 * Every data-bearing number and table row on the site is rendered from
 * site/data.json (generated by scripts/build_site_data.py). The HTML carries
 * only placeholders, so a stale or missing data file degrades to visible
 * dashes and a notice — never to silently wrong numbers.
 *
 * Bindings:
 *   <span data-bind="corpus.num_scenarios" data-fmt="int">—</span>
 *   <tbody data-table="leaderboard"> … placeholder row … </tbody>
 */
(function () {
    "use strict";

    var MISSING_MESSAGE =
        "Live release data unavailable — run `python scripts/build_site_data.py` " +
        "to generate site/data.json, and serve this page over HTTP.";

    var TRACK_LABELS = {
        text_to_action: "Text to action",
        audio_to_action: "Audio to action",
        end_to_end_voice: "End-to-end voice",
        robustness: "Robustness",
        adversarial_compliance: "Adversarial compliance"
    };

    var TRACK_PURPOSE = {
        text_to_action: "Transcript and customer request in, tool trace out.",
        audio_to_action: "Customer audio in, tool trace out.",
        end_to_end_voice: "Customer audio in, spoken response and tool trace out.",
        robustness: "Noise, crosstalk, interruption, disfluency, and low-bandwidth style variants.",
        adversarial_compliance: "Fraud, privacy, prompt injection, policy bypass, and unsafe escalation tests."
    };

    function get(data, path) {
        var value = data;
        var parts = path.split(".");
        for (var i = 0; i < parts.length; i++) {
            if (value == null) { return null; }
            value = value[parts[i]];
        }
        return value == null ? null : value;
    }

    function fmt(value, spec) {
        if (value == null || (typeof value === "number" && !isFinite(value))) { return "—"; }
        switch (spec) {
            case "int": return Math.round(value).toLocaleString("en-US");
            case "num2": return Number(value).toFixed(2);
            case "num3": return Number(value).toFixed(3);
            case "num4": return Number(value).toFixed(4);
            case "pct0": return Math.round(value * 100) + "%";
            case "ms": return Math.round(value).toLocaleString("en-US") + " ms";
            case "money2": return "$" + Number(value).toFixed(2);
            case "passes": return value ? "passes" : "does not pass";
            default: return String(value);
        }
    }

    function text(tag, className, content) {
        var node = document.createElement(tag);
        if (className) { node.className = className; }
        node.textContent = content;
        return node;
    }

    function cell(row, className, content) {
        var td = text("td", className, content);
        row.appendChild(td);
        return td;
    }

    function rankLabel(row) {
        return row.tied ? row.rank + "\u2020" : String(row.rank);
    }

    /* --- table renderers, keyed by data-table attribute --- */

    var renderers = {
        /* index.html: five-up track count grid (divs, not a table). */
        "track-grid": function (container, data) {
            container.textContent = "";
            data.corpus.tracks.forEach(function (track) {
                var box = document.createElement("div");
                box.className = "track";
                box.appendChild(text("strong", null, fmt(track.scenarios, "int")));
                box.appendChild(text("span", null, TRACK_LABELS[track.id] || track.id));
                container.appendChild(box);
            });
        },

        /* index.html: top five of the ranked leaderboard. */
        "leaderboard-top": function (tbody, data) {
            tbody.textContent = "";
            data.leaderboard.rows.slice(0, 5).forEach(function (row) {
                var tr = document.createElement("tr");
                cell(tr, null, rankLabel(row));
                cell(tr, "model", row.model_id);
                cell(tr, "num", fmt(row.trial_coverage, "pct0"));
                cell(tr, row.tied ? "num best" : "num", fmt(row.overall_score, "num2"));
                tbody.appendChild(tr);
            });
        },

        /* results.html: the full ranked leaderboard, one row per CSV row. */
        "leaderboard": function (tbody, data) {
            tbody.textContent = "";
            data.leaderboard.rows.forEach(function (row) {
                var tr = document.createElement("tr");
                cell(tr, "num", rankLabel(row));
                cell(tr, "wrap", "").appendChild(text("strong", null, row.model_id));
                cell(tr, "num", fmt(row.trial_coverage, "pct0"));
                cell(tr, row.tied ? "num best" : "num", fmt(row.overall_score, "num2"));
                ["task_success", "tool_correctness", "sop_compliance", "privacy",
                 "auth_integrity", "safety", "factual_grounding"].forEach(function (metric) {
                    cell(tr, "num", fmt(row[metric], "num3"));
                });
                cell(tr, "num", fmt(row.tokens_per_success, "int"));
                tbody.appendChild(tr);
            });
        },

        /* results.html: oracle / no-op reference anchors. */
        "anchors": function (tbody, data) {
            tbody.textContent = "";
            [
                { key: "oracle", label: "oracle" },
                { key: "noop", label: "noop" }
            ].forEach(function (entry) {
                var anchor = data.anchors[entry.key];
                if (!anchor) { return; }
                var tr = document.createElement("tr");
                var name = cell(tr, "wrap", "");
                var code = document.createElement("code");
                code.textContent = entry.label;
                name.appendChild(code);
                name.appendChild(document.createTextNode(" — " + anchor.description));
                cell(tr, "num", fmt(anchor.overall_score, "num2"));
                cell(tr, "num", fmt(anchor.pass_k, "num2"));
                cell(tr, "num", fmt(anchor.safety, "num3"));
                tbody.appendChild(tr);
            });
        },

        /* results.html: official frontier reference systems. */
        "frontier": function (tbody, data) {
            tbody.textContent = "";
            data.frontier.systems.forEach(function (system) {
                var tr = document.createElement("tr");
                cell(tr, "wrap", "").appendChild(text("strong", null, system.id));
                cell(tr, null, system.input);
                cell(tr, "num", fmt(system.scenarios, "int"));
                cell(tr, "num", fmt(system.trials, "int"));
                cell(tr, "num best", fmt(system.task_success, "num3"));
                cell(tr, "num", fmt(system.ci_low, "num4") + "-" + fmt(system.ci_high, "num4"));
                cell(tr, "num", fmt(system.p50_ttfb_ms, "ms"));
                cell(tr, "num", fmt(system.p95_ttfb_ms, "ms"));
                cell(tr, "num", fmt(system.p95_last_byte_ms, "ms"));
                cell(tr, "num", fmt(system.cost_per_success_usd, "money2"));
                cell(tr, "num", fmt(system.experience, "num3"));
                tbody.appendChild(tr);
            });
        },

        /* results.html: per-track scenario counts with purpose column. */
        "tracks": function (tbody, data) {
            tbody.textContent = "";
            data.corpus.tracks.forEach(function (track) {
                var tr = document.createElement("tr");
                cell(tr, null, "").appendChild(text("strong", null, track.id));
                cell(tr, "num", fmt(track.scenarios, "int"));
                cell(tr, "wrap", TRACK_PURPOSE[track.id] || "");
                tbody.appendChild(tr);
            });
        },

        /* results.html: domain counts, two domains per row. */
        "domains": function (tbody, data) {
            renderPairs(tbody, data.corpus.domains, "scenarios");
        },

        /* results.html: audio perturbation counts, two per row. */
        "perturbations": function (tbody, data) {
            renderPairs(tbody, data.corpus.audio_perturbations, "variants");
        }
    };

    function renderPairs(tbody, entries, countKey) {
        tbody.textContent = "";
        for (var i = 0; i < entries.length; i += 2) {
            var tr = document.createElement("tr");
            cell(tr, null, entries[i].id);
            cell(tr, "num", fmt(entries[i][countKey], "int"));
            cell(tr, null, entries[i + 1] ? entries[i + 1].id : "");
            cell(tr, "num", entries[i + 1] ? fmt(entries[i + 1][countKey], "int") : "");
            tbody.appendChild(tr);
        }
    }

    function render(data) {
        document.querySelectorAll("[data-bind]").forEach(function (node) {
            node.textContent = fmt(get(data, node.getAttribute("data-bind")),
                node.getAttribute("data-fmt"));
        });
        /* Elements marked data-when are claims that only hold for some data
         * states (e.g. the rank-1/2 tie note). They ship hidden and are shown
         * only when the bound value is truthy, so a data change can never
         * leave a stale claim visible. */
        document.querySelectorAll("[data-when]").forEach(function (node) {
            node.hidden = !get(data, node.getAttribute("data-when"));
        });
        document.querySelectorAll("[data-table]").forEach(function (node) {
            var renderer = renderers[node.getAttribute("data-table")];
            if (renderer) { renderer(node, data); }
        });
    }

    function showUnavailable() {
        var banner = document.createElement("div");
        banner.className = "data-status";
        banner.setAttribute("role", "alert");
        banner.textContent = MISSING_MESSAGE;
        document.body.insertBefore(banner, document.body.firstChild);
        /* Placeholders in the markup already read "—" / "not loaded", so the
         * layout stays intact; the banner just says why. */
    }

    document.addEventListener("DOMContentLoaded", function () {
        fetch("data.json", { cache: "no-store" })
            .then(function (response) {
                if (!response.ok) { throw new Error("HTTP " + response.status); }
                return response.json();
            })
            .then(render)
            .catch(showUnavailable);
    });
}());
